package com.metalurgica.sistemagestaoindustrial.mapper;
import com.metalurgica.sistemagestaoindustrial.domain.*; import com.metalurgica.sistemagestaoindustrial.dto.response.*; import org.springframework.stereotype.Component;
@Component public class ImportacaoProducaoMapper { public ImportacaoProducaoResponse toResponse(ImportacaoProducao i){return new ImportacaoProducaoResponse(i.getId(),i.getEmpresa().getId(),i.getSetor().getId(),i.getSetor().getCodigo(),i.getSetor().getNome(),i.getNomeArquivo(),i.getHashArquivo(),i.getStatus().name(),i.getTotalLinhas(),i.getLinhasValidas(),i.getLinhasInvalidas(),i.getLinhasImportadas(),i.getIniciadoEm(),i.getFinalizadoEm(),i.getCreatedAt());} public ResultadoLinhaImportacaoResponse toResponse(ResultadoLinhaImportacao r){return new ResultadoLinhaImportacaoResponse(r.getId(),r.getNumeroLinha(),r.getStatus(),r.getCodigoFuncionario(),r.getCodigoPeca(),r.getCodigoErro(),r.getMensagem());} }
